<script setup>
import {onMounted,ref} from 'vue';
import {api} from './api';
const rows=ref([]),status=ref('OPEN'),page=ref(1),total=ref(0),busy=ref(false),error=ref('');
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){const d=await api('/admin/contact-messages?'+new URLSearchParams({status:status.value,page:page.value}));rows.value=d.items;total.value=d.total}
async function resolve(row){await run(async()=>{await api('/admin/contact-messages/'+row.id,{method:'PATCH',body:{status:row.status==='OPEN'?'RESOLVED':'OPEN'}});await load()})}
async function remove(row){if(!confirm('Permanently delete this contact message and its sender details?'))return;await run(async()=>{await api('/admin/contact-messages/'+row.id,{method:'DELETE'});if(rows.value.length===1&&page.value>1)page.value--;await load()})}
onMounted(()=>run(load));
</script>
<template><section class="panel contact-inbox"><h2>Contact Inbox</h2><p class="muted">Private messages from the Contact page. Reply opens your email app; messages are not emailed automatically.</p><label>Status <select v-model="status" :disabled="busy" @change="page=1;run(load)"><option>OPEN</option><option>RESOLVED</option><option>ALL</option></select></label><p v-if="error" role="alert">{{error}}</p><p v-if="busy" role="status">Loading…</p><article v-for="row in rows" :key="row.id" class="panel"><strong>{{row.topic}} · {{row.status}}</strong><p>{{row.name}} · {{row.email}} · {{new Date(row.created_at*1000).toLocaleString()}}</p><p class="contact-message">{{row.message}}</p><div class="contact-actions"><a class="btn btn-primary" :href="'mailto:'+encodeURIComponent(row.email)+'?subject='+encodeURIComponent('Re: MauryaHub — '+row.topic)">Reply by email</a><button class="btn btn-light" :disabled="busy" @click="resolve(row)">{{row.status==='OPEN'?'Mark resolved':'Reopen'}}</button><button class="btn btn-light" :disabled="busy" @click="remove(row)">Delete</button></div></article><p v-if="!rows.length&&!busy">No messages.</p><div class="contact-actions"><button class="btn btn-light" :disabled="busy||page===1" @click="page--;run(load)">Previous</button><span>Page {{page}} · {{total}} messages</span><button class="btn btn-light" :disabled="busy||page*20>=total" @click="page++;run(load)">Next</button></div></section></template>
<style scoped>.contact-message{white-space:pre-wrap;overflow-wrap:anywhere}.contact-actions{display:flex;flex-wrap:wrap;gap:.6rem;align-items:center}.contact-inbox{margin-block:1rem}.contact-inbox article{margin-top:1rem;overflow-wrap:anywhere}</style>
